-- UTF-8, rerunnable seed for the Tiệm Cà Phê Mare tenant database.
-- Listing facts (address, hours, price band) were verified on Foody/ShopeeFood.
-- Dish names were not exposed by the public listing API on 2026-08-07; these are
-- curated demo products within the published 16,000–38,000 VND price range.
CREATE UNIQUE INDEX IF NOT EXISTS uq_caphemare_productcode ON producttb(productcode) WHERE productcode LIKE 'MARE-%';
ON CONFLICT(productcode) WHERE productcode LIKE 'MARE-%' DO UPDATE SET productname=EXCLUDED.productname,productcatalog=EXCLUDED.productcatalog,productbrand=EXCLUDED.productbrand,productshortdes=EXCLUDED.productshortdes,productlongdes=EXCLUDED.productlongdes,productimageurl1=EXCLUDED.productimageurl1,productimageurl2=EXCLUDED.productimageurl2,productimagedesurl=EXCLUDED.productimagedesurl,productsubcatalog=EXCLUDED.productsubcatalog,productgroupstring=EXCLUDED.productgroupstring,pagekeyword=EXCLUDED.pagekeyword,productpriceamount=EXCLUDED.productpriceamount,productdiscont=EXCLUDED.productdiscont,productpricecurrency=EXCLUDED.productpricecurrency,language=EXCLUDED.language,path=EXCLUDED.path,modifiedtime=NOW(),isvisible=TRUE,isapproved=TRUE,islocked=FALSE,isnew=EXCLUDED.isnew;
